-- ============================================================================
-- ISTAPA - Mise à jour du contenu des 5 filières (source : documents Word)
-- Traduction FR -> EN générée pour content_en / short_description_en,
-- contenu FR nettoyé (suppression du HTML Word/mso) pour content_fr.
-- Compatible MariaDB 10.4 / InnoDB / utf8mb4
-- ============================================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

-- NB : Le titre de la filière id=3 est renommé "Environnement" -> "Gestion
-- Environnementale" / "Environmental Management", pour coller au nom exact
-- utilisé dans le document Word et sur l'affiche ISTAPA. Le slug
-- (hnd-environment) n'est PAS modifié pour ne pas casser les liens/URLs
-- existants.

UPDATE `programs` SET
  `title_fr` = 'Production Animale',
  `title_en` = 'Animal Production',
  `short_description_fr` = 'Compétences scientifiques et techniques pour un élevage durable et la sécurité alimentaire.',
  `short_description_en` = 'Scientific and technical skills for sustainable livestock farming and food security.',
  `content_fr` = '<h2>Présentation du programme</h2><p>L''enseignement supérieur en Production Animale dote les étudiants de compétences scientifiques, techniques et entrepreneuriales. Les opportunités de carrière couvrent le secteur public, l''agro-industrie privée, les ONG et le milieu universitaire, avec de solides perspectives dans l''agriculture commerciale, la sécurité alimentaire et les systèmes d''élevage durables.</p><h3>Points forts du programme</h3><ul><li><strong>Orientation pratique:</strong> les étudiants se forment dans des fermes expérimentales, des ranchs et des laboratoires.</li><li><strong>Axé sur la recherche:</strong> les universités et instituts collaborent avec l''IRAD.</li><li><strong>Intégration technologique:</strong> cours en biotechnologie, insémination artificielle et formulation d''aliments.</li><li><strong>Focus sur la durabilité:</strong> accent mis sur les systèmes d''élevage intelligents face au climat et le bien-être animal.</li></ul><h3>Contenu du programme</h3><ul><li>Sciences animales et zootechnie</li><li>Physiologie animale, nutrition et génétique</li><li>Systèmes de production animale (bovins, volailles, porcs, petits ruminants)</li><li>Gestion des pâturages et des fourrages</li><li>Bases de la santé animale et vétérinaire</li><li>Sélection et biotechnologie</li><li>Technologie de la production animale et domaines connexes</li><li>Agro-industrie d''origine animale</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Élevage, de la Pêche et des Industries Animales (MINEPIA), IRAD, mairies.</p><p><strong>Secteur privé:</strong> startups agroalimentaires dans la volaille, l''aquaculture et les petits ruminants ; exploitations agropastorales (fermes bovines, volailles, porcheries, pisciculture) ; usines d''alimentation animale et entreprises pharmaceutiques vétérinaires ; industries de transformation de la viande et des produits laitiers.</p><p><strong>ONG et organisations internationales:</strong> FAO, GIZ, Banque mondiale, FIDA, ONG promouvant l''élevage durable et les moyens de subsistance ruraux.</p><p><strong>Académie et recherche:</strong> postes d''enseignement et de recherche dans des universités et collèges agropastoraux ; études doctorales en génétique animale, nutrition et systèmes de production.</p><h3>Perspectives</h3><ul><li>Le secteur de l''élevage contribue de manière significative au PIB et à l''emploi rural.</li><li>Demande croissante de protéines animales (viande, lait, œufs) due à la croissance démographique.</li><li>Expansion des fermes commerciales d''aviculture et de porcs dans les centres urbains.</li><li>Perspectives solides en aquaculture et systèmes intégrés culture-élevage.</li><li>Opportunités émergentes en biotechnologie animale, innovation alimentaire et systèmes d''élevage résilients au climat.</li></ul>',
  `content_en` = '<h2>Program Overview</h2><p>Higher education in Animal Production equips students with scientific, technical and entrepreneurial skills. Career opportunities span the public sector, private agribusiness, NGOs and academia, with strong prospects in commercial farming, food security and sustainable livestock systems.</p><h3>Program Highlights</h3><ul><li><strong>Hands-on training:</strong> students train on experimental farms, ranches and in laboratories.</li><li><strong>Research-driven:</strong> universities and institutes collaborate with IRAD.</li><li><strong>Technology integration:</strong> courses in biotechnology, artificial insemination and feed formulation.</li><li><strong>Sustainability focus:</strong> emphasis on climate-smart livestock systems and animal welfare.</li></ul><h3>Program Content</h3><ul><li>Animal science and zootechnics</li><li>Animal physiology, nutrition and genetics</li><li>Livestock production systems (cattle, poultry, pigs, small ruminants)</li><li>Pasture and forage management</li><li>Fundamentals of animal and veterinary health</li><li>Breeding and biotechnology</li><li>Livestock production technology and related fields</li><li>Animal-based agro-industry</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Livestock, Fisheries and Animal Industries (MINEPIA), IRAD, municipal councils.</p><p><strong>Private sector:</strong> agribusiness startups in poultry, aquaculture and small ruminants; agropastoral farms (cattle, poultry, piggeries, fish farming); animal feed plants and veterinary pharmaceutical companies; meat and dairy processing industries.</p><p><strong>NGOs and international organizations:</strong> FAO, GIZ, World Bank, IFAD, NGOs promoting sustainable livestock farming and rural livelihoods.</p><p><strong>Academia and research:</strong> teaching and research positions in universities and agropastoral colleges; doctoral opportunities in animal genetics, nutrition and production systems.</p><h3>Outlook</h3><ul><li>The livestock sector contributes significantly to GDP and rural employment.</li><li>Growing demand for animal protein (meat, milk, eggs) driven by population growth.</li><li>Expansion of commercial poultry and pig farms around urban centers.</li><li>Strong prospects in aquaculture and integrated crop-livestock systems.</li><li>Emerging opportunities in animal biotechnology, food innovation and climate-resilient livestock systems.</li></ul>'
WHERE `id` = 1;

UPDATE `programs` SET
  `title_fr` = 'Production Végétale',
  `title_en` = 'Crop Production',
  `short_description_fr` = 'Compétences agricoles, technologiques et entrepreneuriales modernes pour une agriculture durable.',
  `short_description_en` = 'Modern agricultural, technological and entrepreneurial skills for sustainable farming.',
  `content_fr` = '<h2>Présentation du programme</h2><p>L''enseignement supérieur en Production Végétale dote les étudiants de compétences agricoles, technologiques et entrepreneuriales modernes. Les opportunités de carrière couvrent le gouvernement, l''agro-industrie, les ONG et la recherche, avec de solides perspectives dans l''agriculture durable, l''agro-industrie et l''agriculture numérique.</p><h3>Points forts du programme</h3><ul><li><strong>Orientation pratique:</strong> fort accent sur le travail de terrain, les exploitations agricoles expérimentales et les stages en entreprises agricoles.</li><li><strong>Axée sur la recherche:</strong> les universités gèrent des stations expérimentales sur le maïs, le manioc, le cacao, le café, les cultures horticoles, etc.</li><li><strong>Intégration technologique:</strong> formation en mécanisation, systèmes d''irrigation et biotechnologie.</li><li><strong>Orientation durable:</strong> agriculture intelligente face au climat, agriculture biologique et pratiques de conservation.</li></ul><h3>Contenu du programme</h3><ul><li>Production agricole et science du sol</li><li>Physiologie et génétique des plantes</li><li>Fertilité des sols et nutrition des cultures</li><li>Technologies d''irrigation et de mécanisation</li><li>Gestion intégrée des nuisibles</li><li>Agriculture durable et agriculture respectueuse du climat</li><li>Technologies agro-industrielles des cultures</li><li>Technologie post-récolte et agro-industrie</li><li>Transformation alimentaire</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Agriculture et du Développement Rural (MINADER), IRAD, communes.</p><p><strong>Secteur privé:</strong> startups agroalimentaires, horticulture, agriculture sous serre et production mécanisée ; entreprises agro-industrielles ; entreprises semencières et agrochimiques.</p><p><strong>ONG et organisations internationales:</strong> FAO, GIZ, Banque mondiale, FIDA, ONG promouvant l''agriculture durable et la résilience climatique.</p><p><strong>Académie et recherche:</strong> postes d''enseignement et de recherche dans des universités et collèges agricoles ; études doctorales en sciences des cultures, biotechnologie et agriculture durable.</p><h3>Perspectives</h3><ul><li>L''agriculture camerounaise emploie plus de 60 % de la population, faisant des technologies de production agricole un pilier central du développement national.</li><li>Demande croissante pour une agriculture respectueuse du climat et de précision.</li><li>Expansion de l''entrepreneuriat agroalimentaire dans l''horticulture, la production de semences et la transformation.</li><li>Perspectives solides dans l''agriculture numérique (SIG, drones, IA) pour le suivi des cultures.</li><li>Opportunités dans les cultures d''exportation (cacao, café, banane) et les cultures vivrières stratégiques (manioc, maïs, riz).</li></ul>',
  `content_en` = '<h2>Program Overview</h2><p>Higher education in Crop Production equips students with modern agricultural, technological and entrepreneurial skills. Career opportunities span government, agribusiness, NGOs and research, with strong prospects in sustainable farming, agro-industry and digital agriculture.</p><h3>Program Highlights</h3><ul><li><strong>Hands-on training:</strong> strong emphasis on fieldwork, experimental farms and internships with agricultural companies.</li><li><strong>Research-driven:</strong> universities run experimental stations on maize, cassava, cocoa, coffee, horticultural crops and more.</li><li><strong>Technology integration:</strong> training in mechanization, irrigation systems and biotechnology.</li><li><strong>Sustainability focus:</strong> climate-smart agriculture, organic farming and conservation practices.</li></ul><h3>Program Content</h3><ul><li>Crop production and soil science</li><li>Plant physiology and genetics</li><li>Soil fertility and crop nutrition</li><li>Irrigation and mechanization technologies</li><li>Integrated pest management</li><li>Sustainable and climate-smart agriculture</li><li>Crop agro-industrial technologies</li><li>Post-harvest technology and agro-industry</li><li>Food processing</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Agriculture and Rural Development (MINADER), IRAD, municipal councils.</p><p><strong>Private sector:</strong> agribusiness startups, horticulture, greenhouse farming and mechanized crop production; agro-industrial companies; seed and agrochemical firms.</p><p><strong>NGOs and international organizations:</strong> FAO, GIZ, World Bank, IFAD, NGOs promoting sustainable agriculture and climate resilience.</p><p><strong>Academia and research:</strong> teaching and research positions in universities and agricultural colleges; doctoral opportunities in crop science, biotechnology and sustainable agriculture.</p><h3>Outlook</h3><ul><li>Cameroonian agriculture employs over 60% of the population, making crop production technologies central to national development.</li><li>Growing demand for climate-smart and precision agriculture.</li><li>Expansion of agri-food entrepreneurship in horticulture, seed production and food processing.</li><li>Strong prospects in digital agriculture (GIS, drones, AI) for crop monitoring.</li><li>Opportunities in export-oriented crops (cocoa, coffee, banana) and food-security crops (cassava, maize, rice).</li></ul>'
WHERE `id` = 2;

UPDATE `programs` SET
  `title_fr` = 'Gestion Environnementale',
  `title_en` = 'Environmental Management',
  `short_description_fr` = 'Compétences techniques et politiques pour la résilience climatique et le développement durable.',
  `short_description_en` = 'Technical and policy skills for climate resilience and sustainable development.',
  `content_fr` = '<h2>Présentation du programme</h2><p>L''enseignement supérieur en Gestion de l''Environnement dote les étudiants de compétences techniques et orientées vers les politiques. Les opportunités de carrière couvrent le gouvernement, l''industrie privée, les ONG et le milieu universitaire, avec de solides perspectives en matière de résilience climatique, d''innovation verte et de développement durable.</p><h3>Points forts du programme</h3><ul><li><strong>Approche multidisciplinaire:</strong> combine écologie, économie, droit et ingénierie pour des solutions environnementales holistiques.</li><li><strong>Apprentissage appliqué:</strong> travail de terrain, analyse en laboratoire et stages auprès d''ONG et d''agences gouvernementales.</li><li><strong>Intégration des politiques:</strong> accent marqué sur la législation environnementale et les cadres de développement durable.</li><li><strong>Orientation recherche:</strong> les étudiants participent à des projets portant sur la déforestation, le recyclage des déchets et les énergies renouvelables.</li><li><strong>Collaboration internationale:</strong> partenariats avec des organisations telles que le WWF, le PNUD, la GIZ, la FAO et la Banque mondiale pour la formation et le soutien à la recherche.</li></ul><h3>Contenu du programme</h3><ul><li>Droit et politique de l''environnement</li><li>Gestion des déchets et contrôle de la pollution</li><li>Adaptation et atténuation du changement climatique</li><li>Développement durable et gestion des ressources naturelles</li><li>Agriculture durable</li><li>Écologie et conservation de la biodiversité</li><li>Contrôle de la pollution</li><li>SIG et analyse des données environnementales</li><li>Évaluation de l''impact environnemental et social</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Environnement, de la Protection de la Nature et du Développement Durable (MINEPDED), Ministère de l''Agriculture et du Développement Rural (MINADER), conseils municipaux.</p><p><strong>Secteur privé:</strong> bureaux d''études et de conseil en environnement (EIES, audit et conformité), départements de durabilité d''entreprise, entreprises d''énergie renouvelable et de recyclage des déchets.</p><p><strong>ONG et organisations internationales:</strong> WWF, PNUD, GIZ, FAO et Banque mondiale sur la conservation et la résilience climatique.</p><p><strong>Académie et recherche:</strong> postes d''enseignement et de recherche dans des universités et instituts environnementaux ; études doctorales en sciences de l''environnement ou adaptation au changement climatique.</p><h3>Perspectives</h3><ul><li>Le secteur de la gestion environnementale s''étend en raison des engagements nationaux dans le cadre de l''Accord de Paris sur le climat.</li><li>Croissance des initiatives d''économie verte et de développement urbain durable.</li><li>Demande croissante de professionnels dans l''évaluation des risques climatiques, les énergies renouvelables et la gouvernance environnementale.</li><li>Zones de croissance prévues : analyse des données environnementales et cartographie SIG, économie circulaire et valorisation des déchets, crédit carbone et financement durable.</li></ul>',
  `content_en` = '<h2>Program Overview</h2><p>Higher education in Environmental Management equips students with technical and policy-oriented skills. Career opportunities span government, private industry, NGOs and academia, with strong prospects in climate resilience, green innovation and sustainable development.</p><h3>Program Highlights</h3><ul><li><strong>Multidisciplinary approach:</strong> combines ecology, economics, law and engineering for holistic environmental solutions.</li><li><strong>Applied learning:</strong> fieldwork, laboratory analysis and internships with NGOs and government agencies.</li><li><strong>Policy integration:</strong> strong emphasis on environmental legislation and sustainable development frameworks.</li><li><strong>Research orientation:</strong> students take part in projects on deforestation, waste recycling and renewable energy.</li><li><strong>International collaboration:</strong> partnerships with organizations such as WWF, UNDP, GIZ, FAO and the World Bank for training and research support.</li></ul><h3>Program Content</h3><ul><li>Environmental law and policy</li><li>Waste management and pollution control</li><li>Climate change adaptation and mitigation</li><li>Sustainable development and natural resource management</li><li>Sustainable agriculture</li><li>Ecology and biodiversity conservation</li><li>Pollution control</li><li>GIS and environmental data analysis</li><li>Environmental and social impact assessment</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Environment, Nature Protection and Sustainable Development (MINEPDED), Ministry of Agriculture and Rural Development (MINADER), municipal councils.</p><p><strong>Private sector:</strong> environmental consulting firms (ESIA, audit and compliance), corporate sustainability departments, renewable energy and waste recycling companies.</p><p><strong>NGOs and international organizations:</strong> WWF, UNDP, GIZ, FAO and World Bank on conservation and climate resilience.</p><p><strong>Academia and research:</strong> teaching and research positions in universities and environmental institutes; doctoral opportunities in environmental science or climate change adaptation.</p><h3>Outlook</h3><ul><li>The environmental management sector is expanding due to national commitments under the Paris Climate Agreement.</li><li>Growth of green economy initiatives and sustainable urban development.</li><li>Rising demand for professionals in climate risk assessment, renewable energy and environmental governance.</li><li>Expected growth areas: environmental data analysis and GIS mapping, circular economy and waste valorization, carbon credits and sustainable finance.</li></ul>'
WHERE `id` = 3;

UPDATE `programs` SET
  `title_fr` = 'Énergies Renouvelables',
  `title_en` = 'Renewable Energy',
  `short_description_fr` = 'Compétences techniques, entrepreneuriales et politiques pour l''électrification durable.',
  `short_description_en` = 'Technical, entrepreneurial and policy skills for sustainable electrification.',
  `content_fr` = '<h2>Présentation du programme</h2><p>L''enseignement supérieur en Énergies Renouvelables dote les étudiants de compétences techniques, entrepreneuriales et politiques. Les opportunités de carrière couvrent le gouvernement, l''industrie privée, les ONG et le milieu universitaire, avec de solides perspectives en électrification, résilience climatique et innovation verte. Les diplômés peuvent poursuivre des carrières dans les secteurs solaire, éolien, hydroélectrique et bioénergétique, avec des opportunités croissantes dans les projets nationaux et internationaux d''électrification et de développement durable.</p><h3>Contenu du programme</h3><ul><li>Fondamentaux du génie électrique et énergétique</li><li>Technologies des énergies renouvelables</li><li>Conception et installation de systèmes photovoltaïques solaires</li><li>Conversion de l''énergie éolienne</li><li>Conversion de l''énergie hydroélectrique</li><li>Systèmes de biomasse</li><li>Efficacité énergétique et gestion</li><li>Durabilité environnementale et politique</li><li>Gestion de projet et entrepreneuriat dans les technologies vertes</li><li>Droit de l''environnement</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère de l''Eau et de l''Énergie (MINEE), SONATREL, AER, SONADEL, mairies.</p><p><strong>Secteur privé:</strong> startups solaires et énergétiques ; cabinets de conseil en ingénierie axés sur les infrastructures durables ; entreprises de construction et industrielles mettant en œuvre des systèmes économes en énergie ; opportunités dans les universités et centres de recherche pour l''innovation dans les technologies renouvelables.</p><p><strong>ONG et organisations internationales:</strong> PNUD, GIZ, Banque mondiale, WWF.</p><p><strong>Académie et recherche:</strong> postes d''enseignement et de recherche dans des universités et instituts ; études doctorales en systèmes d''énergie renouvelable et adaptation au climat.</p><h3>Perspectives</h3><ul><li>Le secteur des énergies renouvelables au Cameroun se développe rapidement.</li><li>Marché en croissance pour les entreprises d''installation solaire, d''audit énergétique et d''éco-conseil.</li><li>Le gouvernement vise à atteindre 25 % de part d''énergie renouvelable d''ici 2035.</li><li>Augmentation des investissements dans les mini-réseaux solaires et la modernisation de l''hydroélectricité.</li><li>Demande régionale d''ingénieurs énergétiques compétents dans les technologies durables.</li></ul>',
  `content_en` = '<h2>Program Overview</h2><p>Higher education in Renewable Energy equips students with technical, entrepreneurial and policy skills. Career opportunities span government, private industry, NGOs and academia, with strong prospects in electrification, climate resilience and green innovation. Graduates can pursue careers in the solar, wind, hydropower and bioenergy sectors, with growing opportunities in national and international electrification and sustainable development projects.</p><h3>Program Content</h3><ul><li>Fundamentals of electrical and energy engineering</li><li>Renewable energy technologies</li><li>Solar photovoltaic system design and installation</li><li>Wind energy conversion</li><li>Hydropower energy conversion</li><li>Biomass systems</li><li>Energy efficiency and management</li><li>Environmental sustainability and policy</li><li>Project management and entrepreneurship in green technologies</li><li>Environmental law</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Water Resources and Energy (MINEE), SONATREL, AER, SONADEL, municipal councils.</p><p><strong>Private sector:</strong> solar and energy startups; engineering consulting firms focused on sustainable infrastructure; construction and industrial companies implementing energy-efficient systems; opportunities in universities and research centers for innovation in renewable technologies.</p><p><strong>NGOs and international organizations:</strong> UNDP, GIZ, World Bank, WWF.</p><p><strong>Academia and research:</strong> teaching and research positions in universities and institutes; doctoral opportunities in renewable energy systems and climate adaptation.</p><h3>Outlook</h3><ul><li>Cameroon''s renewable energy sector is growing rapidly.</li><li>Growing market for solar installation, energy audit and eco-consulting firms.</li><li>The government aims to reach a 25% share of renewable energy by 2035.</li><li>Increased investment in solar mini-grids and hydropower modernization.</li><li>Regional demand for energy engineers skilled in sustainable technologies.</li></ul>'
WHERE `id` = 4;

UPDATE `programs` SET
  `title_fr` = 'Gestion Forestière',
  `title_en` = 'Forestry Management',
  `short_description_fr` = 'Compétences techniques et politiques pour la foresterie durable et la résilience climatique.',
  `short_description_en` = 'Technical and policy skills for sustainable forestry and climate resilience.',
  `content_fr` = '<h2>Présentation du programme</h2><p>L''enseignement supérieur en Gestion Forestière dote les étudiants de compétences techniques et orientées politiques. Les diplômés peuvent s''attendre à des carrières dans le secteur public, industriel, les ONG et le milieu universitaire, avec des opportunités croissantes dans la foresterie durable, la résilience climatique et l''innovation verte.</p><h3>Points forts du programme</h3><ul><li><strong>Formation multidisciplinaire:</strong> combine la foresterie, la faune, les sciences de l''environnement et la transformation industrielle du bois.</li><li><strong>Travail de terrain appliqué:</strong> fort accent sur les compétences pratiques : inventaires forestiers, cartographie SIG, suivi de la faune et transformation industrielle du bois.</li><li><strong>Focus sur la durabilité:</strong> intégration de la résilience climatique, de la protection des écosystèmes et de la gestion forestière communautaire.</li><li><strong>Innovation dans la technologie du bois:</strong> développement de matériaux bio-based, composites et applications de conception.</li><li><strong>Collaboration internationale:</strong> partenariats avec des universités occidentales et des organisations telles que GIZ et WWF pour la formation et le soutien à la recherche.</li></ul><h3>Contenu du programme</h3><ul><li>Exploitation forestière</li><li>Industrie du bois</li><li>Protection des écosystèmes forestiers</li><li>Innovation dans la technologie du bois</li><li>Gestion participative des forêts</li><li>Études d''impact environnemental</li><li>Technologie forestière et faune</li><li>Conservation de la faune</li><li>Surveillance des écosystèmes</li><li>Évaluation de la biodiversité</li><li>Analyse des politiques</li></ul><h3>Débouchés professionnels</h3><p><strong>Secteur public:</strong> Ministère des Forêts et de la Faune (MINFOF), Agence Nationale de Développement Forestier (ANAFOR), mairies.</p><p><strong>Secteur privé:</strong> entreprises forestières, cabinets de conseil environnemental, écotourisme et gestion des réserves fauniques.</p><p><strong>ONG et organisations internationales:</strong> projets du WWF, de la FAO, de la GIZ et de la Banque mondiale sur la conservation des forêts et l''adaptation au climat ; initiatives de gestion forestière communautaire.</p><p><strong>Recherche et académie:</strong> enseignement et recherche en foresterie, biodiversité et gestion durable des ressources ; études doctorales en foresterie, changement climatique ou biologie de la conservation.</p><h3>Perspectives</h3><ul><li>Le Cameroun est le deuxième pays le plus riche en ressources forestières d''Afrique centrale, faisant de la gestion forestière un secteur stratégique.</li><li>Demande croissante pour la certification forestière durable et les produits en bois écologiques.</li><li>Expansion des projets forestiers communautaires pour autonomiser les populations rurales.</li><li>Rôle croissant des outils numériques (SIG, IA, télédétection) dans la surveillance forestière.</li><li>Fortes perspectives dans l''atténuation du changement climatique, les marchés du carbone et la conservation de la biodiversité.</li></ul>',
  `content_en` = '<h2>Program Overview</h2><p>Higher education in Forestry Management equips students with technical and policy-oriented skills. Graduates can expect careers in the public, industrial, NGO and academic sectors, with growing opportunities in sustainable forestry, climate resilience and green innovation.</p><h3>Program Highlights</h3><ul><li><strong>Multidisciplinary training:</strong> combines forestry, wildlife, environmental science and industrial wood processing.</li><li><strong>Applied fieldwork:</strong> strong emphasis on practical skills: forest inventories, GIS mapping, wildlife monitoring and industrial wood processing.</li><li><strong>Sustainability focus:</strong> integration of climate resilience, ecosystem protection and community forest management.</li><li><strong>Wood technology innovation:</strong> development of bio-based materials, composites and design applications.</li><li><strong>International collaboration:</strong> partnerships with Western universities and organizations such as GIZ and WWF for training and research support.</li></ul><h3>Program Content</h3><ul><li>Forest exploitation</li><li>Wood industry</li><li>Forest ecosystem protection</li><li>Wood technology innovation</li><li>Participatory forest management</li><li>Environmental impact studies</li><li>Forestry and wildlife technology</li><li>Wildlife conservation</li><li>Ecosystem monitoring</li><li>Biodiversity assessment</li><li>Policy analysis</li></ul><h3>Career Opportunities</h3><p><strong>Public sector:</strong> Ministry of Forestry and Wildlife (MINFOF), National Forestry Development Agency (ANAFOR), municipal councils.</p><p><strong>Private sector:</strong> forestry companies, environmental consulting firms, ecotourism and wildlife reserve management.</p><p><strong>NGOs and international organizations:</strong> WWF, FAO, GIZ and World Bank projects on forest conservation and climate adaptation; community forest management initiatives.</p><p><strong>Research and academia:</strong> teaching and research in forestry, biodiversity and sustainable resource management; doctoral opportunities in forestry, climate change or conservation biology.</p><h3>Outlook</h3><ul><li>Cameroon is Central Africa''s second most forest-rich country, making forestry management a strategic sector.</li><li>Growing demand for sustainable forest certification and eco-friendly wood products.</li><li>Expansion of community forestry projects to empower rural populations.</li><li>Growing role of digital tools (GIS, AI, remote sensing) in forest monitoring.</li><li>Strong prospects in climate change mitigation, carbon markets and biodiversity conservation.</li></ul>'
WHERE `id` = 5;

COMMIT;
